/bin/bash -lc "python - <<'PY'
import numpy as np
from scipy.ndimage import label
A=np.load('source_pixels.npz')['rgb'].astype(np.int16)
for t in range(1,96):
 d=np.max(np.abs(A[t]-A[t-1]),2)>8
 lab,n=label(d)
 cs=[]
 for i in range(1,n+1):
  ys,xs=np.where(lab==i)
  if len(xs)>=3: cs.append((len(xs),round(xs.mean(),1),round(ys.mean(),1),(xs.min(),ys.min(),xs.max(),ys.max())))
 if t<25 or t%5==0: print(t,sorted(cs,reverse=True)[:6])
PY"
